={{ (() => {
  const ids = (value) => String(value || '').split(/[^0-9]+/).filter(Boolean);
  const num = (value) => {
    const match = String(value || '').match(/\d{1,7}/);
    return match ? match[0] : '';
  };
  const search = String($fromAI('search', 'Texto de nombre o marca, por ejemplo corolla o toyota. Cadena vacia si no hay texto.', 'string') || '').replace(/["\\\n\r{}]/g, ' ').replace(/\s+/g, ' ').trim();
  const marca = ids($fromAI('marca_ids', 'IDs numericos de carone_marca separados por coma. Cadena vacia si no filtras por marca.', 'string'));
  const modelo = ids($fromAI('modelo_ids', 'IDs numericos de carone_modelo separados por coma. Cadena vacia si no filtras por modelo.', 'string'));
  const fuel = ids($fromAI('fuel_ids', 'IDs numericos de carone_fuel separados por coma. Cadena vacia si no filtras por combustible.', 'string'));
  const body = ids($fromAI('type_ids', 'IDs numericos de carone_type separados por coma. Cadena vacia si no filtras por carroceria.', 'string'));
  const yearFrom = num($fromAI('year_from', 'Anio desde, cuatro digitos. Para un anio exacto repetilo en year_to. Vacio si no filtras por anio.', 'string'));
  const yearTo = num($fromAI('year_to', 'Anio hasta, cuatro digitos. Vacio si no filtras por anio.', 'string'));
  const kmFrom = num($fromAI('km_from', 'Kilometraje desde. 0 es 0km. Vacio si no filtras por km.', 'string'));
  const kmTo = num($fromAI('km_to', 'Kilometraje hasta. Vacio si no filtras por km.', 'string'));
  const usadosRaw = String($fromAI('solo_usados', 'si solo si busca un usado para comprar. no si es 0km, listado general, o el usado que entrega. vacio si no aplica.', 'string') || '').trim().toLowerCase();
  const usados = usadosRaw === 'si' || usadosRaw === 'sí' || usadosRaw === 'true' || usadosRaw === '1';
  const pageSize = 500;
  const filters = [];
  const addIn = (field, values) => {
    if (values.length) filters.push(field + ': { in: [' + values.map((id) => '"' + id + '"').join(', ') + '] }');
  };
  addIn('carone_marca', marca);
  addIn('carone_modelo', modelo);
  addIn('carone_fuel', fuel);
  addIn('carone_type', body);
  if (yearFrom && yearTo) filters.push('carone_year: { from: "' + yearFrom + '", to: "' + yearTo + '" }');
  if (kmFrom !== '' && kmTo !== '') filters.push('carone_mileage: { from: "' + kmFrom + '", to: "' + kmTo + '" }');
  if (usados) filters.push('carone_estado: { eq: "96" }');
  if (!search && !filters.length) {
    return JSON.stringify({ query: '{ __typename }' });
  }
  const args = [];
  if (search) args.push('search: "' + search + '"');
  if (filters.length) args.push('filter: { ' + filters.join(', ') + ' }');
  args.push('pageSize: ' + pageSize);
  args.push('currentPage: 1');
  const query = '{ products(' + args.join(', ') + ') { total_count items { sku name carone_year carone_mileage carone_marca_data { label } carone_modelo_data { label } carone_fuel_data { label } carone_type_data { label } } } }';
  return JSON.stringify({ query });
})() }}

